const item = $input.first().json;
const output = item.output ?? item;
const script = output.tiktok_video_script;

if (!script || !Array.isArray(script.scenes) || script.scenes.length === 0) {
  throw new Error("TikTok video script or scenes are missing.");
}

const hookDuration = 3;
const closingDuration = 3;
const elements = [];

const addText = (text, time, duration, fontSize = "7 vmin") => {
  elements.push({
    type: "text",
    track: 1,
    time,
    duration,
    text: String(text || ""),
    width: "86%",
    height: "30%",
    x: "7%",
    y: "35%",
    fill_color: "#ffffff",
    font_family: "Montserrat",
    font_weight: "800",
    font_size: fontSize,
    x_alignment: "50%",
    y_alignment: "50%"
  });
};

addText(script.hook, 0, hookDuration);

let time = hookDuration;

for (const scene of script.scenes) {
  const duration = Math.max(
    3,
    Math.min(5, Number(scene.duration_seconds) || 4)
  );

  addText(scene.on_screen_text, time, duration);
  time += duration;
}

addText(script.closing_cta, time, closingDuration, "6 vmin");

const totalDuration = time + closingDuration;

return [{
  json: {
    renderBody: {
      output_format: "mp4",
      width: 1080,
      height: 1920,
      render_scale: 1,
      duration: totalDuration,
      elements: [{
        type: "composition",
        track: 1,
        time: 0,
        duration: totalDuration,
        fill_color: "#091122",
        elements
      }]
    }
  }
}];
